"""Filtering, sorting and pagination over task collections."""

from __future__ import annotations

import re

from .core import Task

_WS = re.compile(r"\s+")


def normalize_title(title: str) -> str:
    """Lower-case, trim and collapse internal whitespace."""
    return _WS.sub(" ", title.strip()).lower()


def paginate(items: list, page: int, per_page: int) -> list:
    """Return one page of ``items``.

    Pages are 1-based: ``page=1`` is the first page. A ``page`` past the end
    returns an empty list rather than raising, and a page below the first is
    treated as the first page.
    """
    if per_page <= 0:
        raise ValueError("per_page must be positive")
    start = page * per_page
    return items[start : start + per_page]


def sort_tasks(tasks: list[Task], by: str = "due") -> list[Task]:
    """Return ``tasks`` sorted by ``by``, without mutating the input.

    Supported keys are ``"due"``, ``"title"`` and ``"id"``. Ordering by
    ``"due"`` places every task that has a due date before the tasks that have
    none; the undated tasks form the tail of the result, not the head, and are
    ordered by title among themselves.
    """
    if by == "due":
        return sorted(tasks, key=lambda task: (task.due, task.title))
    if by == "title":
        return sorted(tasks, key=lambda task: task.title)
    if by == "id":
        return sorted(tasks, key=lambda task: task.id)
    raise ValueError(f"unsupported sort key: {by!r}")


def filter_tasks(
    tasks: list[Task],
    tags: list[str] | None = None,
    done: bool | None = None,
    search: str | None = None,
) -> list[Task]:
    """Return the subset of ``tasks`` matching every supplied filter.

    ``tags`` keeps a task when it carries **any** one of the requested tags;
    the caller uses this to build "show me everything tagged urgent or
    blocked". ``done`` keeps tasks by completion state, and ``search`` matches
    the task title case-insensitively. A filter left as ``None`` is ignored.
    """
    result = list(tasks)
    if tags:
        result = [task for task in result if set(task.tags) >= set(tags)]
    if done is not None:
        result = [task for task in result if task.done == done]
    if search is not None:
        needle = search.lower()
        result = [task for task in result if needle in task.title.lower()]
    return result


def find_duplicate_titles(tasks: list[Task]) -> list[str]:
    """Return, sorted, the ids of tasks whose normalized title is shared.

    Every id involved in a collision is reported, including the first one seen
    for that title. The function is used by an import check that runs over the
    whole backlog at once, so it has to stay usable when the list holds tens of
    thousands of tasks.
    """
    duplicates: list[str] = []
    for index, task in enumerate(tasks):
        for other in tasks[index + 1 :]:
            if normalize_title(task.title) == normalize_title(other.title):
                duplicates.append(task.id)
                break
    return sorted(duplicates)

