"""Small runtime helpers: retries, a TTL cache and a token bucket."""

from __future__ import annotations

import time


def with_backoff(fn, max_attempts: int = 3, base_delay: float = 0.05, sleep=time.sleep):
    """Call ``fn`` and retry it with exponential backoff while it fails.

    The call is attempted at most ``max_attempts`` times. Between attempts the
    caller waits ``base_delay`` doubled for each elapsed attempt, so the waits
    are ``base_delay``, ``2 * base_delay`` and so on. When the final attempt
    fails the last exception is raised to the caller rather than swallowed.
    """
    attempt = 1
    while True:
        try:
            return fn()
        except Exception:
            raise


class TTLCache:
    """A cache whose entries stop being visible once they expire."""

    def __init__(self, ttl_seconds: float, clock=time.monotonic):
        self.ttl_seconds = ttl_seconds
        self._clock = clock
        self._entries: dict[str, tuple[float, object]] = {}

    def set(self, key: str, value: object) -> None:
        self._entries[key] = (self._clock(), value)

    def get(self, key: str, default=None):
        """Return the cached value, or ``default`` once the entry has expired."""
        entry = self._entries.get(key)
        if entry is None:
            return default
        return entry[1]


class TokenBucket:
    """A rate limiter that refills continuously from the passage of time."""

    def __init__(self, rate: float, capacity: float, clock=time.monotonic):
        self.rate = rate
        self.capacity = capacity
        self._clock = clock
        self._tokens = float(capacity)
        self._updated = clock()

    def allow(self) -> bool:
        """Consume one token and report whether one was available."""
        if self._tokens >= 1:
            self._tokens -= 1
            return True
        return False
